package dev.anvilcraft.lib.v2.rendering.optimization.occlusion;

import net.minecraft.client.renderer.SubmitNodeCollection;
import net.minecraft.client.renderer.SubmitNodeStorage;
import net.minecraft.client.renderer.feature.phase.FeatureRenderPhase;
import net.minecraft.client.renderer.feature.phase.TranslucentFeatureRenderPhase;
import net.minecraft.client.renderer.feature.submit.SubmitNode;
import java.util.ArrayList;
import java.util.List;
import org.jspecify.annotations.Nullable;

/** Records the phase nodes generated by an entity, then transfers them without changing their phases. */
public class OcclusionSubmitNodeCollection extends SubmitNodeCollection {
    private final OcclusionCuller culler;
    private final SubmitNodeCollection original;
    private @Nullable OcclusionKey currentKey;

    public OcclusionSubmitNodeCollection(SubmitNodeStorage storage, OcclusionCuller culler, SubmitNodeCollection original) {
        super(original.shadows == original.oitTranslucent, new TranslucentFeatureRenderPhase());
        this.culler = culler;
        this.original = original;
    }

    public void beginOcclusionRecord(OcclusionKey key) {
        if (this.currentKey != null) throw new IllegalStateException("Occlusion record already active");
        this.currentKey = key;
    }

    public void endOcclusionRecord() {
        if (this.currentKey == null) throw new IllegalStateException("No occlusion record active");
        List<Object> features = new ArrayList<>();
        List<FeatureRenderPhase<?>> source = this.allPhases();
        List<FeatureRenderPhase<?>> target = this.original.allPhases();
        for (int i = 0; i < source.size(); i++) transfer(source.get(i), target.get(i), features);
        transfer(this.seeThrough, this.original.seeThrough, features);
        this.culler.submitFeatureKey(this.currentKey, features);
        this.currentKey = null;
    }

    @SuppressWarnings("unchecked")
    private static void transfer(FeatureRenderPhase<?> source, FeatureRenderPhase<?> target, List<Object> features) {
        // Source and target are the same phase of collections with identical transparency settings.
        FeatureRenderPhase<SubmitNode> destination = (FeatureRenderPhase<SubmitNode>) target;
        source.sortInto((submit, ordered) -> {
            features.add(submit);
            destination.submit(submit);
        });
    }
}
